import indexJson from "../../data/creative-library.index.json";
import type { LibraryIndex } from "./types";
import { createLibraryLookup, type LibraryLookup } from "./lookup";
import { loadOpenRegistry, type OpenAsset, type OpenSource } from "./open-registry";

/** Server-side access to the imported Creative Library index (generated by scripts/import-creative-library.ts). */
const index = indexJson as unknown as LibraryIndex;
let lookup: LibraryLookup | null = null;

export function getLibraryIndex(): LibraryIndex {
  return index;
}

export function getLibrary(): LibraryLookup {
  if (!lookup) lookup = createLibraryLookup(index);
  return lookup;
}

let open: { assets: Map<string, OpenAsset>; sources: Map<string, OpenSource> } | null = null;
function openLookup() {
  if (!open) {
    const r = loadOpenRegistry();
    open = { assets: new Map((r?.assets ?? []).map((a) => [a.id, a])), sources: new Map((r?.sources ?? []).map((x) => [x.id, x])) };
  }
  return open;
}

/** Map of assetId → colours, used by validation contrast checks (ModVerse library and Graphics Library). */
export function assetColorsFor(ids: string[]): Record<string, string[]> {
  const lib = getLibrary();
  const out: Record<string, string[]> = {};
  for (const id of ids) {
    const a = lib.get(id) ?? (id.startsWith("og-") ? openLookup().assets.get(id) : undefined);
    if (a) out[id] = a.colors;
  }
  return out;
}

/** Credit lines for Graphics Library assets used in a design (licence, creator; the attribution text where required). */
export function assetCreditsFor(ids: string[]): Record<string, string> {
  const out: Record<string, string> = {};
  const o = openLookup();
  for (const id of ids) {
    const a = id.startsWith("og-") ? o.assets.get(id) : undefined;
    const src = a ? o.sources.get(a.source) : undefined;
    if (a && src) out[id] = `"${a.name}" — ${src.attribution}${src.attributionRequired ? " (credit required)" : ""}`;
  }
  return out;
}
